"use client";

import { useState, useRef, useEffect } from "react";
import useVoice from "@/hooks/useVoice";
import { useSpeech } from "@/hooks/useSpeech";

export default function ChatInput({ onSend, loading }) {
  const [text, setText] = useState("");
  const textareaRef = useRef(null);

  const saveHistory = (msg) => {
    try {
      let history = JSON.parse(localStorage.getItem("omnix_chat_history") || "[]");
      history.unshift({ id: Date.now(), title: msg });
      localStorage.setItem("omnix_chat_history", JSON.stringify(history.slice(0, 50)));
    } catch {}
  };

  const { listening, startListening, stopListening } = useVoice((wakeText) => {
    if (!wakeText.trim()) return;
    onSend(`You said: "${wakeText}"`);
  });

  const { stop } = useSpeech();

  // Auto-resize textarea
  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, 180) + "px";
  }, [text]);

  const handleSend = () => {
    const trimmed = text.trim();
    if (!trimmed || loading) return;
    stop();
    onSend(trimmed);
    saveHistory(trimmed);
    setText("");
    if (textareaRef.current) textareaRef.current.style.height = "auto";
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleChange = (e) => {
    setText(e.target.value);
    if (typeof window !== "undefined") window.speechSynthesis.cancel();
  };

  const handleFocus = () => {
    if (typeof window !== "undefined") window.speechSynthesis.cancel();
  };

  const handleMicClick = () => {
    if (listening) { stopListening(); return; }
    stop();
    startListening();
    setTimeout(() => stopListening(), 5000);
  };

  const isEmpty = !text.trim();

  return (
    <div
      className="input-ring relative flex flex-col rounded-2xl border"
      style={{
        background: "rgba(255,255,255,0.05)",
        borderColor: "rgba(255,255,255,0.1)",
        boxShadow: "0 20px 50px -20px rgba(0,0,0,0.5)",
      }}
    >
      {/* Textarea */}
      <textarea
        ref={textareaRef}
        value={text}
        onChange={handleChange}
        onFocus={handleFocus}
        onKeyDown={handleKeyDown}
        placeholder="Message OMNIX… (Shift+Enter for new line)"
        rows={1}
        className="w-full resize-none bg-transparent px-4 pt-3.5 pb-2 text-[14.5px] leading-relaxed outline-none placeholder-white/30 text-white/90 caret-indigo-400"
        style={{ minHeight: "52px", maxHeight: "180px", fontFamily: "inherit" }}
        disabled={loading}
      />

      {/* Toolbar row */}
      <div className="flex items-center justify-between px-3 pb-3 pt-1">
        {/* Left: Hints */}
        <p className="hidden sm:block text-[11px] text-white/20 select-none">
          {isEmpty ? "Ask anything…" : `${text.length} chars · Shift+Enter for new line`}
        </p>

        {/* Right: Action buttons */}
        <div className="flex items-center gap-2 ml-auto">
          {/* Mic button */}
          <button
            onClick={handleMicClick}
            aria-label={listening ? "Stop listening" : "Voice input"}
            className={`relative flex h-9 w-9 items-center justify-center rounded-xl transition-all duration-300 ${
              listening
                ? "shadow-[0_0_0_3px_rgba(99,102,241,0.35)]"
                : "text-white/50 hover:text-white/80"
            }`}
            style={
              listening
                ? { background: "linear-gradient(135deg, #4f46e5, #7c3aed, #c026d3)", color: "white" }
                : { background: "rgba(255,255,255,0.07)", border: "1px solid rgba(255,255,255,0.09)" }
            }
          >
            {listening && (
              <span className="absolute inset-0 rounded-xl border-2 border-indigo-400 animate-ping opacity-60" />
            )}
            <svg
              className={`relative z-10 h-4 w-4 transition-transform duration-300 ${listening ? "scale-110" : "scale-95"}`}
              fill="currentColor"
              viewBox="0 0 24 24"
            >
              <path d="M12 14a3 3 0 003-3V7a3 3 0 10-6 0v4a3 3 0 003 3zm5-3a1 1 0 10-2 0 3 3 0 11-6 0 1 1 0 10-2 0 5 5 0 0010 0zm-5 9a1 1 0 001-1v-3h-2v3a1 1 0 001 1z" />
            </svg>
          </button>

          {/* Send button */}
          <button
            onClick={handleSend}
            disabled={isEmpty || loading}
            aria-label="Send message"
            className={`flex h-9 w-9 items-center justify-center rounded-xl transition-all duration-200 ${
              isEmpty || loading
                ? "opacity-30 cursor-not-allowed"
                : "hover:scale-105 hover:shadow-[0_10px_24px_-10px_rgba(99,102,241,0.7)] active:scale-95"
            }`}
            style={{
              background: "linear-gradient(135deg, #4f46e5, #7c3aed, #c026d3)",
              boxShadow: isEmpty || loading ? "none" : "0 8px 20px -10px rgba(99,102,241,0.5)",
            }}
          >
            {loading ? (
              <svg className="h-4 w-4 text-white animate-spin" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
              </svg>
            ) : (
              <svg className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
              </svg>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}
