"use client";

import { useState } from "react";
import { useChat } from "@/hooks/useChat";
import Modal from "@/components/ui/Modal";

export default function ChatHeader({ onMenuToggle, onNewChat }) {
  const [isModelModalOpen, setIsModelModalOpen] = useState(false);
  const { resetChat } = useChat();

  const handleNewChat = () => {
    resetChat();
    onNewChat?.();
  };

  const copyModelName = async () => {
    try { await navigator.clipboard.writeText("gemini-3-flash-preview"); } catch {}
  };

  return (
    <>
      <header
        className="shrink-0 flex h-14 items-center justify-between px-4 sm:px-5 gap-3 border-b"
        style={{
          borderColor: "rgba(255,255,255,0.06)",
          background: "rgba(6,7,15,0.85)",
          backdropFilter: "blur(20px)",
        }}
      >
        {/* Left: Hamburger (mobile) + Brand */}
        <div className="flex items-center gap-3 min-w-0">
          {/* Mobile menu toggle */}
          <button
            onClick={onMenuToggle}
            className="lg:hidden flex h-9 w-9 shrink-0 items-center justify-center rounded-xl transition-all"
            style={{ background: "rgba(255,255,255,0.06)" }}
            aria-label="Open sidebar"
          >
            <svg className="h-4.5 w-4.5 text-white/70" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5M3.75 17.25h16.5" />
            </svg>
          </button>

          {/* Logo + Name */}
          <div className="flex items-center gap-2.5 min-w-0">
            <div className="relative shrink-0">
              <div className="h-8 w-8 rounded-xl bg-gradient-to-br from-indigo-500 via-violet-500 to-fuchsia-500 flex items-center justify-center shadow-lg animate-pulse-glow">
                <svg className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                </svg>
              </div>
            </div>
            <div className="flex flex-col leading-none min-w-0">
              <span className="text-sm font-bold tracking-tight gradient-text">OMNIX</span>
              <span className="text-[10px] text-white/35 truncate">Gemini 3 Flash Preview</span>
            </div>
          </div>

          {/* Model chip — hidden on small screens */}
          <button
            onClick={() => setIsModelModalOpen(true)}
            className="hidden sm:flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium text-white/50 transition-all hover:text-white/80 hover:border-white/15"
            style={{ borderColor: "rgba(255,255,255,0.08)", background: "rgba(255,255,255,0.04)" }}
          >
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse" />
            Gemini 3 Flash
            <svg className="h-3 w-3 opacity-50" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" />
            </svg>
          </button>
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-2 shrink-0">
          {/* New chat — text on md+ */}
          <button
            onClick={handleNewChat}
            className="hidden sm:flex items-center gap-1.5 rounded-xl px-3.5 py-2 text-[13px] font-medium text-white/70 transition-all hover:text-white/90"
            style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.08)" }}
          >
            <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            New chat
          </button>

          {/* New chat icon (mobile) */}
          <button
            onClick={handleNewChat}
            className="sm:hidden flex h-9 w-9 items-center justify-center rounded-xl text-white/60 hover:text-white/90 transition-all"
            style={{ background: "rgba(255,255,255,0.06)" }}
            aria-label="New chat"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
          </button>

          {/* Info */}
          <button
            onClick={() => setIsModelModalOpen(true)}
            className="flex h-9 w-9 items-center justify-center rounded-xl text-white/50 transition-all hover:text-white/80"
            style={{ background: "rgba(255,255,255,0.05)" }}
            aria-label="Model info"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M11.25 11.25l.041-.02a.75.75 0 011.063.852l-.708 2.836a.75.75 0 001.063.853l.041-.021M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-3.75h.008v.008H12V8.25z" />
            </svg>
          </button>

          {/* Avatar */}
          <div
            className="flex h-9 w-9 items-center justify-center rounded-xl text-xs font-bold text-white shadow-md"
            style={{ background: "linear-gradient(135deg, #6366f1, #8b5cf6, #d946ef)" }}
          >
            U
          </div>
        </div>
      </header>

      {/* Model Info Modal */}
      <Modal
        open={isModelModalOpen}
        onClose={() => setIsModelModalOpen(false)}
        title="Model Information"
      >
        <div className="space-y-4">
          <p className="text-sm text-white/60 leading-relaxed">
            This conversation is powered by Google&apos;s{" "}
            <strong className="text-white/85">Gemini 3 Flash Preview</strong> — a fast, high-quality
            model designed for natural, intelligent conversations.
          </p>

          <div
            className="rounded-xl p-4"
            style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.07)" }}
          >
            <div className="flex items-center justify-between gap-4">
              <div>
                <p className="text-[10px] font-semibold uppercase tracking-widest text-white/30 mb-1">
                  Active model
                </p>
                <p className="text-sm font-medium text-white/85 font-mono">gemini-3-flash-preview</p>
              </div>
              <button
                onClick={copyModelName}
                className="shrink-0 rounded-lg px-3 py-1.5 text-xs font-medium text-white/70 transition-all hover:text-white"
                style={{ background: "rgba(255,255,255,0.08)", border: "1px solid rgba(255,255,255,0.1)" }}
              >
                Copy
              </button>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse shadow-[0_0_8px_rgba(52,211,153,0.6)]" />
            <span className="text-xs text-white/40">Model is active and responding</span>
          </div>
        </div>
      </Modal>
    </>
  );
}
