"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import ChatHeader from "./ChatHeader";
import ChatList from "./ChatList";
import ChatInput from "./ChatInput";
import TypingIndicator from "./TypingIndicator";
import { useChat } from "@/hooks/useChat";
import { useSpeech } from "@/hooks/useSpeech";

// ─── LocalStorage helpers ────────────────────────────────────────────────────
const SESSIONS_KEY = "omnix_sessions";
const ACTIVE_KEY   = "omnix_active_session";

function readSessions() {
  try { return JSON.parse(localStorage.getItem(SESSIONS_KEY) || "[]"); }
  catch { return []; }
}

function writeSessions(sessions) {
  try { localStorage.setItem(SESSIONS_KEY, JSON.stringify(sessions)); }
  catch {}
}

function readActiveId() {
  try { return localStorage.getItem(ACTIVE_KEY) || null; }
  catch { return null; }
}

function writeActiveId(id) {
  try { localStorage.setItem(ACTIVE_KEY, id); }
  catch {}
}

// ─── Prompt suggestion cards ─────────────────────────────────────────────────
const SUGGESTION_CARDS = [
  {
    icon: "✦",
    label: "Draft an email",
    prompt: "Draft a professional email to request a meeting with a potential client.",
    gradient: "from-indigo-500/20 to-violet-500/10",
    border: "border-indigo-500/20",
  },
  {
    icon: "⬡",
    label: "Explain a concept",
    prompt: "Explain how neural networks learn in simple terms.",
    gradient: "from-violet-500/20 to-fuchsia-500/10",
    border: "border-violet-500/20",
  },
  {
    icon: "◈",
    label: "Write code",
    prompt: "Write a Python function to sort a list of dictionaries by a specific key.",
    gradient: "from-fuchsia-500/20 to-pink-500/10",
    border: "border-fuchsia-500/20",
  },
  {
    icon: "◎",
    label: "Brainstorm ideas",
    prompt: "Give me 10 creative startup ideas in the AI/ML space.",
    gradient: "from-sky-500/20 to-indigo-500/10",
    border: "border-sky-500/20",
  },
];

// ─── Sidebar ─────────────────────────────────────────────────────────────────
function Sidebar({ activeChatId, onSelectChat, sessions, onNewChat, onDeleteChat, onClose }) {
  return (
    <div className="relative flex h-full flex-col p-4">
      <div className="pointer-events-none absolute -top-16 -right-10 h-32 w-32 rounded-full bg-indigo-500/15 blur-3xl" />
      <div className="pointer-events-none absolute bottom-10 -left-8 h-24 w-24 rounded-full bg-fuchsia-500/10 blur-3xl" />

      {/* Branding */}
      <div className="relative flex items-center justify-between mb-6">
        <div>
          <div className="flex items-center gap-2">
            <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-linear-to-br from-indigo-500 via-violet-500 to-fuchsia-500 shadow-lg">
              <svg className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
              </svg>
            </div>
            <span className="text-sm font-semibold gradient-text">OMNIX</span>
          </div>
          <p className="mt-1 text-[10px] font-medium uppercase tracking-widest text-white/30">
            Conversations
          </p>
        </div>

        {/* Mobile close */}
        <button
          onClick={onClose}
          className="lg:hidden flex h-8 w-8 items-center justify-center rounded-lg bg-white/5 text-white/50 hover:bg-white/10 hover:text-white/80 transition-all"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* New Chat */}
      <button
        onClick={() => { onNewChat(); onClose?.(); }}
        className="group mb-4 flex w-full items-center gap-2.5 rounded-xl border border-indigo-500/25 bg-linear-to-r from-indigo-600/20 to-violet-600/15 px-3.5 py-2.5 text-sm font-medium text-white/85 transition-all duration-200 hover:from-indigo-600/30 hover:to-violet-600/25 hover:border-indigo-500/40 hover:shadow-[0_8px_20px_-10px_rgba(99,102,241,0.4)]"
      >
        <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-lg bg-white/10 text-xs font-bold">+</span>
        New conversation
      </button>

      {/* Session List */}
      <div className="flex-1 overflow-y-auto space-y-1.5 pr-0.5">
        {sessions.length === 0 ? (
          <p className="mt-4 text-center text-[12px] text-white/25">No conversations yet</p>
        ) : (
          <>
            <p className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-white/25">Recent</p>
            {sessions.map((session) => (
              <div key={session.id} className="group relative">
                <button
                  onClick={() => { onSelectChat(session.id); onClose?.(); }}
                  className={`w-full rounded-xl border px-3 py-2.5 text-left transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500/50 ${
                    activeChatId === session.id
                      ? "sidebar-item-active border-indigo-500/22 text-white"
                      : "border-transparent text-white/55 hover:bg-white/5 hover:border-white/8 hover:text-white/80"
                  }`}
                >
                  {activeChatId === session.id && (
                    <span className="absolute left-0 top-1/2 h-7 w-0.5 -translate-y-1/2 rounded-r-full bg-linear-to-b from-indigo-400 to-fuchsia-500" />
                  )}
                  <div className="flex items-center gap-2.5 pr-6">
                    <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-xs font-semibold transition-all ${
                      activeChatId === session.id
                        ? "bg-linear-to-br from-indigo-500/40 to-violet-500/30 text-white"
                        : "bg-white/6 text-white/50 group-hover:bg-white/10 group-hover:text-white/70"
                    }`}>
                      {session.title.slice(0, 1).toUpperCase()}
                    </span>
                    <span className="truncate text-[13px] font-medium leading-tight">{session.title}</span>
                  </div>
                  {activeChatId === session.id && (
                    <span className="absolute right-7 top-1/2 -translate-y-1/2 h-1.5 w-1.5 rounded-full bg-emerald-400 shadow-[0_0_6px_rgba(52,211,153,0.7)]" />
                  )}
                </button>

                {/* Delete button */}
                <button
                  onClick={(e) => { e.stopPropagation(); onDeleteChat(session.id); }}
                  className="absolute right-2 top-1/2 -translate-y-1/2 flex h-6 w-6 items-center justify-center rounded-lg text-white/0 group-hover:text-white/35 hover:text-white/70! hover:bg-white/10 transition-all"
                  aria-label="Delete conversation"
                >
                  <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            ))}
          </>
        )}
      </div>

      {/* Footer */}
      <div className="mt-4 border-t border-white/6 pt-4">
        <div className="flex items-center gap-2.5 rounded-xl px-2 py-2">
          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-linear-to-br from-indigo-400 to-fuchsia-500 text-xs font-bold text-white shadow-md">
            U
          </div>
          <div className="min-w-0">
            <p className="truncate text-[12px] font-semibold text-white/80">My Account</p>
            <p className="truncate text-[10px] text-white/35">Gemini 3 Flash Preview</p>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── Welcome Screen ───────────────────────────────────────────────────────────
function WelcomeScreen({ onSend }) {
  return (
    <div className="flex flex-col items-center justify-center min-h-full py-12 px-4 text-center animate-fade-in">
      <div className="relative mb-8">
        <div className="absolute inset-0 rounded-full bg-linear-to-br from-indigo-500 via-violet-500 to-fuchsia-500 opacity-40 blur-2xl scale-110" />
        <div className="relative flex h-20 w-20 items-center justify-center rounded-2xl bg-linear-to-br from-indigo-500 via-violet-500 to-fuchsia-500 shadow-2xl">
          <svg className="h-9 w-9 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
          </svg>
        </div>
      </div>

      <h1 className="text-3xl sm:text-4xl font-bold tracking-tight text-white mb-3">
        Hello, I&apos;m <span className="gradient-text">OMNIX</span>
      </h1>
      <p className="text-base text-white/50 max-w-sm mb-10 leading-relaxed">
        Your intelligent AI partner. Ask me anything — I&apos;m here to help you think, build, and create.
      </p>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-lg">
        {SUGGESTION_CARDS.map((card) => (
          <button
            key={card.label}
            onClick={() => onSend(card.prompt)}
            className={`group relative flex flex-col items-start gap-2 rounded-2xl border ${card.border} bg-linear-to-br ${card.gradient} px-4 py-4 text-left transition-all duration-250 hover:scale-[1.02] hover:shadow-[0_16px_40px_-18px_rgba(99,102,241,0.3)] focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500/50`}
          >
            <span className="text-2xl leading-none">{card.icon}</span>
            <div>
              <p className="text-sm font-semibold text-white/90 mb-0.5">{card.label}</p>
              <p className="text-[12px] text-white/40 leading-snug line-clamp-2">{card.prompt}</p>
            </div>
            <svg className="absolute right-3 top-3 h-3.5 w-3.5 text-white/20 transition-all group-hover:text-white/50 group-hover:translate-x-0.5 group-hover:-translate-y-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 19.5l15-15M19.5 4.5H8.25M19.5 4.5V15.75" />
            </svg>
          </button>
        ))}
      </div>
    </div>
  );
}

// ─── Main Layout ──────────────────────────────────────────────────────────────
export default function ChatLayout() {
  const { messages, sendMessage, loading, resetChat, loadChat } = useChat();
  const { speak } = useSpeech();
  const bottomRef = useRef(null);
  const scrollRef = useRef(null);

  const [activeChatId, setActiveChatId] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const isFirstMessageRef = useRef(true);

  // Load sessions from localStorage on mount (client only)
  useEffect(() => {
    const saved = readSessions();
    setSessions(saved);
    const lastId = readActiveId();
    if (lastId && saved.find((s) => s.id === lastId)) {
      const session = saved.find((s) => s.id === lastId);
      setActiveChatId(lastId);
      loadChat(session.messages);
      isFirstMessageRef.current = false;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // After every message change: persist the active session
  useEffect(() => {
    if (!activeChatId || messages.length === 0) return;
    setSessions((prev) => {
      const updated = prev.map((s) =>
        s.id === activeChatId ? { ...s, messages } : s
      );
      writeSessions(updated);
      return updated;
    });
  }, [messages, activeChatId]);

  // TTS on AI reply
  useEffect(() => {
    if (!messages.length) return;
    const last = messages[messages.length - 1];
    if (last.role === "assistant") speak(last.content);
    return () => {
      if (typeof window !== "undefined") window.speechSynthesis.cancel();
    };
  }, [messages, speak]);

  // Auto-scroll
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); return; }
    const distFromBottom = el.scrollHeight - el.clientHeight - el.scrollTop;
    if (distFromBottom < 200) el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
  }, [messages, loading]);

  // ESC closes sidebar
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && setSidebarOpen(false);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);

  // ── Wrap sendMessage to create a session on the first message ──
  const handleSend = useCallback(async (text) => {
    if (!text.trim()) return;

    // First message in this session → create a new session entry
    if (isFirstMessageRef.current) {
      const newId = String(Date.now());
      const title = text.slice(0, 48) + (text.length > 48 ? "…" : "");
      const newSession = { id: newId, title, messages: [] };

      setSessions((prev) => {
        const updated = [newSession, ...prev];
        writeSessions(updated);
        return updated;
      });
      setActiveChatId(newId);
      writeActiveId(newId);
      isFirstMessageRef.current = false;
    }

    sendMessage(text);
  }, [sendMessage]);

  // ── New chat ──
  const handleNewChat = useCallback(() => {
    resetChat();
    setActiveChatId(null);
    writeActiveId("");
    isFirstMessageRef.current = true;
  }, [resetChat]);

  // ── Select existing session ──
  const handleSelectChat = useCallback((id) => {
    const session = sessions.find((s) => s.id === id);
    if (!session) return;
    resetChat();
    loadChat(session.messages);
    setActiveChatId(id);
    writeActiveId(id);
    isFirstMessageRef.current = false;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sessions, resetChat, loadChat]);

  // ── Delete session ──
  const handleDeleteChat = useCallback((id) => {
    setSessions((prev) => {
      const updated = prev.filter((s) => s.id !== id);
      writeSessions(updated);
      return updated;
    });
    if (activeChatId === id) {
      handleNewChat();
    }
  }, [activeChatId, handleNewChat]);

  const sidebarProps = {
    activeChatId,
    onSelectChat: handleSelectChat,
    sessions,
    onNewChat: handleNewChat,
    onDeleteChat: handleDeleteChat,
  };

  return (
    <div className="relative min-h-screen h-screen overflow-hidden" style={{ background: "var(--bg-base)" }}>

      {/* Background */}
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <div className="absolute -top-80 -left-80 h-[700px] w-[700px] rounded-full bg-indigo-600/12 blur-3xl animate-orbit-slow" />
        <div className="absolute -bottom-80 -right-80 h-[800px] w-[800px] rounded-full bg-fuchsia-600/10 blur-3xl" />
        <div className="absolute top-1/3 left-[40%] h-[500px] w-[500px] rounded-full bg-violet-600/8 blur-3xl animate-float-slow" />
        <div
          className="absolute inset-0 opacity-[0.015]"
          style={{
            backgroundImage: `radial-gradient(circle, rgba(255,255,255,0.8) 1px, transparent 1px)`,
            backgroundSize: "40px 40px",
          }}
        />
      </div>

      {/* Mobile overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm lg:hidden animate-fade-in"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Mobile drawer */}
      <aside
        className={`fixed left-0 top-0 z-50 h-full w-72 lg:hidden transition-transform duration-300 ${
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        }`}
        style={{
          background: "rgba(8,9,20,0.97)",
          backdropFilter: "blur(24px)",
          borderRight: "1px solid rgba(255,255,255,0.07)",
        }}
      >
        <Sidebar {...sidebarProps} onClose={() => setSidebarOpen(false)} />
      </aside>

      {/* Main layout */}
      <div className="relative flex h-screen w-full">

        {/* Desktop sidebar */}
        <aside
          className="hidden lg:flex w-64 xl:w-72 shrink-0 h-full flex-col"
          style={{
            background: "rgba(8,9,20,0.85)",
            backdropFilter: "blur(24px)",
            borderRight: "1px solid rgba(255,255,255,0.06)",
          }}
        >
          <Sidebar {...sidebarProps} onClose={() => {}} />
        </aside>

        {/* Chat area */}
        <div className="flex flex-1 flex-col h-full min-w-0">

          <ChatHeader
            onMenuToggle={() => setSidebarOpen((v) => !v)}
            onNewChat={handleNewChat}
          />

          <div className="flex-1 overflow-hidden">
            <div ref={scrollRef} className="h-full overflow-y-auto" style={{ scrollBehavior: "smooth" }}>
              <div className="mx-auto w-full max-w-3xl px-4 py-6 sm:px-6 lg:px-8">
                {messages.length === 0 && !loading ? (
                  <WelcomeScreen onSend={handleSend} />
                ) : (
                  <div className="space-y-2 pb-4">
                    <ChatList messages={messages} />
                    {loading && <TypingIndicator />}
                    <div ref={bottomRef} />
                  </div>
                )}
              </div>
            </div>
          </div>

          <div
            className="shrink-0 border-t"
            style={{ borderColor: "rgba(255,255,255,0.06)", background: "rgba(6,7,15,0.92)", backdropFilter: "blur(20px)" }}
          >
            <div className="mx-auto w-full max-w-3xl px-4 py-4 sm:px-6 lg:px-8">
              <ChatInput onSend={handleSend} loading={loading} />
              <p className="mt-2.5 text-center text-[11px] text-white/20">
                OMNIX can make mistakes. Verify important information.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
