"use client";

import { useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

function CopyButton({ text, small }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(text).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };

  if (small) {
    return (
      <button
        onClick={handleCopy}
        className="flex items-center gap-1 rounded-md px-2 py-1 text-[11px] font-medium text-white/40 transition-all hover:text-white/70"
        style={{ background: "rgba(255,255,255,0.05)" }}
      >
        {copied ? (
          <>
            <svg className="h-3 w-3 text-emerald-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
            </svg>
            Copied
          </>
        ) : (
          <>
            <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 17.25v3.375c0 .621-.504 1.125-1.125 1.125h-9.75a1.125 1.125 0 01-1.125-1.125V7.875c0-.621.504-1.125 1.125-1.125H6.75a9.06 9.06 0 011.5.124m7.5 10.376h3.375c.621 0 1.125-.504 1.125-1.125V11.25c0-4.46-3.243-8.161-7.5-8.876a9.06 9.06 0 00-1.5-.124H9.375c-.621 0-1.125.504-1.125 1.125v3.5m7.5 10.375H9.375a1.125 1.125 0 01-1.125-1.125v-9.25m12 6.625v-1.875a3.375 3.375 0 00-3.375-3.375h-1.5a1.125 1.125 0 01-1.125-1.125v-1.5a3.375 3.375 0 00-3.375-3.375H9.75" />
            </svg>
            Copy
          </>
        )}
      </button>
    );
  }

  return (
    <button
      onClick={handleCopy}
      className="flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-[11px] font-medium transition-all"
      style={{
        color: copied ? "rgb(52,211,153)" : "rgba(255,255,255,0.45)",
        background: "rgba(255,255,255,0.06)",
        border: "1px solid rgba(255,255,255,0.08)",
      }}
    >
      {copied ? (
        <>
          <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
          </svg>
          Copied!
        </>
      ) : (
        <>
          <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 17.25v3.375c0 .621-.504 1.125-1.125 1.125h-9.75a1.125 1.125 0 01-1.125-1.125V7.875c0-.621.504-1.125 1.125-1.125H6.75a9.06 9.06 0 011.5.124m7.5 10.376h3.375c.621 0 1.125-.504 1.125-1.125V11.25c0-4.46-3.243-8.161-7.5-8.876a9.06 9.06 0 00-1.5-.124H9.375c-.621 0-1.125.504-1.125 1.125v3.5m7.5 10.375H9.375a1.125 1.125 0 01-1.125-1.125v-9.25m12 6.625v-1.875a3.375 3.375 0 00-3.375-3.375h-1.5a1.125 1.125 0 01-1.125-1.125v-1.5a3.375 3.375 0 00-3.375-3.375H9.75" />
          </svg>
          Copy
        </>
      )}
    </button>
  );
}

function CodeBlock({ children, className }) {
  const lang = className?.replace("language-", "") || "code";
  const codeText = String(children).replace(/\n$/, "");

  return (
    <div className="code-block my-3 text-sm">
      <div className="code-block-header">
        <span>{lang}</span>
        <CopyButton text={codeText} />
      </div>
      <div className="overflow-x-auto">
        <pre className="px-4 py-4 text-[13px] leading-relaxed" style={{ color: "#c9d1d9", margin: 0 }}>
          <code>{codeText}</code>
        </pre>
      </div>
    </div>
  );
}

export default function ChatMessage({ message }) {
  const isUser = message.role === "user";

  return (
    <div className={`w-full flex animate-chat-entry ${isUser ? "justify-end" : "justify-start"}`}>
      <div className={`flex items-start gap-3 max-w-[90%] sm:max-w-[80%] ${isUser ? "flex-row-reverse" : ""}`}>

        {/* Avatar */}
        <div className="shrink-0 mt-0.5">
          {isUser ? (
            <div className="h-8 w-8 rounded-xl flex items-center justify-center text-[11px] font-bold text-white shadow-md"
              style={{ background: "linear-gradient(135deg, #6366f1, #8b5cf6)" }}>
              U
            </div>
          ) : (
            <div className="relative h-8 w-8 rounded-xl flex items-center justify-center shadow-md overflow-hidden"
              style={{ background: "linear-gradient(135deg, #4f46e5, #7c3aed, #c026d3)" }}>
              <svg className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
              </svg>
            </div>
          )}
        </div>

        {/* Message Bubble */}
        <div className="group relative min-w-0">
          {/* Name label */}
          <p className={`mb-1.5 text-[11px] font-semibold uppercase tracking-widest ${isUser ? "text-right text-indigo-400/70" : "text-violet-400/70"}`}>
            {isUser ? "You" : "OMNIX"}
          </p>

          <div
            className={`relative rounded-2xl px-4 py-3 text-[14.5px] leading-relaxed ${
              isUser
                ? "bubble-user text-white rounded-tr-sm"
                : "bubble-ai text-white/90 rounded-tl-sm backdrop-blur-xl"
            }`}
          >
            {isUser ? (
              <p className="whitespace-pre-wrap break-words">{message.content}</p>
            ) : (
              <div className="prose-omnix break-words">
                <ReactMarkdown
                  remarkPlugins={[remarkGfm]}
                  components={{
                    p: ({ children }) => <div className="mb-[0.65em] last:mb-0">{children}</div>,
                    ul: ({ children }) => <ul>{children}</ul>,
                    ol: ({ children }) => <ol>{children}</ol>,
                    li: ({ children }) => <li>{children}</li>,
                    strong: ({ children }) => <strong>{children}</strong>,
                    em: ({ children }) => <em>{children}</em>,
                    blockquote: ({ children }) => <blockquote>{children}</blockquote>,
                    a: ({ href, children }) => <a href={href} target="_blank" rel="noopener noreferrer">{children}</a>,
                    h1: ({ children }) => <h1>{children}</h1>,
                    h2: ({ children }) => <h2>{children}</h2>,
                    h3: ({ children }) => <h3>{children}</h3>,
                    table: ({ children }) => (
                      <div className="overflow-x-auto my-3">
                        <table>{children}</table>
                      </div>
                    ),
                    th: ({ children }) => <th>{children}</th>,
                    td: ({ children }) => <td>{children}</td>,
                    code({ inline, className, children }) {
                      if (inline) {
                        return (
                          <code
                            className="rounded-md px-1.5 py-0.5 text-[13px] font-mono"
                            style={{
                              background: "rgba(99,102,241,0.18)",
                              color: "#c4b5fd",
                              border: "1px solid rgba(99,102,241,0.2)",
                            }}
                          >
                            {children}
                          </code>
                        );
                      }
                      return <CodeBlock className={className}>{children}</CodeBlock>;
                    },
                  }}
                >
                  {message.content}
                </ReactMarkdown>
              </div>
            )}
          </div>

          {/* Action bar on hover (AI only) */}
          {!isUser && (
            <div className="mt-1.5 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-200">
              <CopyButton text={message.content} small />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
